    float ez = a.Z * (1 - fx) * (1 - fy) + b.Z * fx * (1 - fy) + c.Z * (1 - fx) * fy + d.Z * fx * fy;
    float m = std::sqrt(ex * ex + ey * ey + ez * ez);
